import {FIELD,ROLES,GROUP_SEEDS,addSeedMatch} from './data.js';
import {times,occurrenceDates,validDateTime} from './dates.js';
export const STATE_KEY='staseravolley-v002-state-v1',SETTINGS_KEY='staseravolley-v002-settings-v1';
export class RuleError extends Error{constructor(code){super(code);this.code=code;}}
const fail=code=>{throw new RuleError(code);};
const clone=s=>structuredClone(s),values=o=>Object.values(o);
const id=(s,prefix)=>`${prefix}-${++s.seq}`;
export const canManage=(s,personId,groupId)=>!!s.groups[groupId]&&(s.groups[groupId].ownerId===personId||s.groups[groupId].adminIds.includes(personId)||s.authorizedAdmins.includes(personId));
export const memberOf=(s,p,g)=>s.memberships[`${g}:${p}`]?.status==='active';
export function activeBookings(s,matchId,now=Date.now()){return values(s.bookings).filter(b=>b.matchId===matchId&&(b.status==='confirmed'||b.status==='pending'&&s.requests[b.requestId]?.status==='pending'&&Date.parse(s.requests[b.requestId].expiresAt)>now));}
export function slotsFor(match){return FIELD.concat(Array.from({length:Math.max(0,match.capacity-12)},(_,i)=>'r'+(i+1)));}
export const availableCount=(s,matchId,now=Date.now())=>Math.max(0,s.matches[matchId].capacity-activeBookings(s,matchId,now).length);
export const myBooking=(s,p,m,now=Date.now())=>activeBookings(s,m,now).find(b=>b.personId===p);
function notify(s,recipientId,type,details,now){const nid=id(s,'notice');s.notifications[nid]={id:nid,recipientId,type,...details,createdAt:new Date(now).toISOString(),read:false};}
function record(s,type,actorId,details,now){s.history.push({id:id(s,'history'),type,actorId,...details,createdAt:new Date(now).toISOString()});}
function assertManager(s,actorId,gid){if(!canManage(s,actorId,gid))fail('unauthorized');}
function assertFuture(match,now){if(!match||match.status!=='active'||Date.parse(match.startsAt)<=now)fail('matchClosed');}
function finishRequest(s,r,status,actorId,now){if(r.status!=='pending')fail('alreadyDecided');r.status=status;r.decidedBy=actorId;r.decidedAt=new Date(now).toISOString();const b=r.bookingId&&s.bookings[r.bookingId];if(b)b.status=status==='accepted'?'confirmed':status;if(r.type==='membership'&&status==='accepted')s.memberships[`${r.groupId}:${r.personId}`]={groupId:r.groupId,personId:r.personId,status:'active',role:'member'};record(s,status,actorId,{requestId:r.id,groupId:r.groupId,matchId:r.matchId||null,personId:r.personId},now);notify(s,r.personId,status,{requestId:r.id,groupId:r.groupId,matchId:r.matchId||null},now);}
export function reconcile(input,now=Date.now()){
 const s=clone(input);let changed=false;for(const r of values(s.requests))if(r.status==='pending'&&r.type==='booking'&&(Date.parse(r.expiresAt)<=now||!s.matches[r.matchId]||Date.parse(s.matches[r.matchId].startsAt)<=now)){finishRequest(s,r,'expired','system',now);changed=true;}
 for(const seed of GROUP_SEEDS){const group=s.groups[seed.id];if(group&&!values(s.matches).some(m=>m.groupId===group.id&&m.seeded&&m.status==='active'&&Date.parse(m.startsAt)>now)){const before=Object.keys(s.matches).length;addSeedMatch(s,group,now);changed=changed||Object.keys(s.matches).length!==before;}}
 if(changed)s.revision++;return changed?s:input;
}
export function transition(input,actorId,action,p={},now=Date.now()){
 const s=clone(reconcile(input,now));if(!s.profiles[actorId])fail('unknownPerson');
 if(action==='JOIN_GROUP'){
  const g=s.groups[p.groupId];if(!g)fail('notFound');if(memberOf(s,actorId,g.id)||values(s.requests).some(r=>r.groupId===g.id&&r.personId===actorId&&r.type==='membership'&&r.status==='pending'))fail('duplicateRequest');
  if(!g.memberApproval){s.memberships[`${g.id}:${actorId}`]={groupId:g.id,personId:actorId,status:'active',role:'member'};record(s,'joined',actorId,{groupId:g.id},now);}else{const rid=id(s,'request');s.requests[rid]={id:rid,type:'membership',personId:actorId,recipientId:g.ownerId,groupId:g.id,status:'pending',createdAt:new Date(now).toISOString(),expiresAt:null};notify(s,g.ownerId,'newRequest',{requestId:rid,groupId:g.id},now);}
 }else if(action==='BOOK'){
  const m=s.matches[p.matchId];assertFuture(m,now);if(!p.slot)fail('chooseSeat');if(myBooking(s,actorId,m.id,now))fail('duplicateBooking');if(!slotsFor(m).includes(p.slot))fail('invalidSeat');if(!availableCount(s,m.id,now))fail('full');if(activeBookings(s,m.id,now).some(b=>b.slot===p.slot))fail('occupied');
  const g=s.groups[m.groupId],bid=id(s,'booking'),rid=g.bookingApproval?id(s,'request'):null;s.bookings[bid]={id:bid,personId:actorId,matchId:m.id,slot:p.slot,status:rid?'pending':'confirmed',requestId:rid,createdAt:new Date(now).toISOString(),priceCents:m.priceCents,paymentStatus:'unpaid'};
  if(rid){s.requests[rid]={id:rid,type:'booking',personId:actorId,recipientId:g.ownerId,groupId:g.id,matchId:m.id,bookingId:bid,slot:p.slot,status:'pending',createdAt:new Date(now).toISOString(),expiresAt:new Date(Math.min(now+s.config.holdHours*3600000,Date.parse(m.startsAt))).toISOString()};notify(s,g.ownerId,'newRequest',{requestId:rid,groupId:g.id,matchId:m.id},now);}else notify(s,actorId,'confirmed',{matchId:m.id,groupId:g.id},now);
 }else if(action==='DECIDE'){
  const r=s.requests[p.requestId];if(!r)fail('notFound');assertManager(s,actorId,r.groupId);if(r.status==='expired')fail('requestExpired');if(r.status!=='pending')fail('alreadyDecided');if(r.type==='booking'){assertFuture(s.matches[r.matchId],now);if(Date.parse(r.expiresAt)<=now)fail('requestExpired');const b=s.bookings[r.bookingId];if(!b||b.status!=='pending')fail('alreadyDecided');if(activeBookings(s,r.matchId,now).some(other=>other.id!==b.id&&(other.slot===b.slot||other.personId===b.personId)))fail('occupied');}finishRequest(s,r,p.accept?'accepted':'rejected',actorId,now);
 }else if(action==='CANCEL'){
  const b=s.bookings[p.bookingId];if(!b||b.personId!==actorId)fail('unauthorized');if(!['pending','confirmed'].includes(b.status))fail('notActive');const m=s.matches[b.matchId];assertFuture(m,now);if(b.requestId&&s.requests[b.requestId]?.status==='pending')finishRequest(s,s.requests[b.requestId],'cancelled',actorId,now);b.status='cancelled';record(s,'cancelled',actorId,{matchId:m.id,bookingId:b.id,groupId:m.groupId},now);
  if(b.paymentStatus==='paid'){const payment=values(s.payments).find(x=>x.bookingId===b.id&&x.type==='charge'),refund=Date.parse(m.startsAt)-now>=24*3600000?payment.amountCents:0;const pid=id(s,'payment');s.payments[pid]={id:pid,bookingId:b.id,type:'refund',amountCents:refund,feeCents:0,totalCents:refund,method:payment.method,createdAt:new Date(now).toISOString()};b.paymentStatus=refund?'refunded':'retained';}
 }else if(action==='MOVE'){
  const b=s.bookings[p.bookingId];if(!b||b.personId!==actorId||b.status!=='confirmed')fail('unauthorized');const m=s.matches[b.matchId];assertFuture(m,now);if(!slotsFor(m).includes(p.slot))fail('invalidSeat');if(activeBookings(s,m.id,now).some(x=>x.id!==b.id&&x.slot===p.slot))fail('occupied');b.slot=p.slot;record(s,'moved',actorId,{matchId:m.id,slot:p.slot},now);
 }else if(action==='PAY'){
  const b=s.bookings[p.bookingId];if(!b||b.personId!==actorId)fail('unauthorized');if(b.status!=='confirmed')fail('paymentNotAllowed');assertFuture(s.matches[b.matchId],now);if(b.paymentStatus!=='unpaid')fail('alreadyPaid');if(!['Satispay','PayPal'].includes(p.method))fail('invalidPayment');const amountCents=b.priceCents,feeCents=Math.round(amountCents*.05),pid=id(s,'payment');s.payments[pid]={id:pid,bookingId:b.id,type:'charge',amountCents,feeCents,totalCents:amountCents+feeCents,method:p.method,createdAt:new Date(now).toISOString()};b.paymentStatus='paid';notify(s,actorId,'paid',{matchId:b.matchId},now);
 }else if(action==='READ_NOTICES'){
  for(const n of values(s.notifications))if(n.recipientId===actorId&&(!p.id||p.id===n.id))n.read=true;
 }else if(action==='GROUP_SETTINGS'){
  const g=s.groups[p.groupId];if(!g)fail('notFound');assertManager(s,actorId,g.id);g.memberApproval=!!p.memberApproval;g.bookingApproval=!!p.bookingApproval;record(s,'settingsChanged',actorId,{groupId:g.id},now);
 }else if(action==='CREATE_GROUP'){
  const name=String(p.name||'').trim(),venue=String(p.venue||'').trim(),city=String(p.city||'').trim();if(!Number.isInteger(Number(p.weekday))||Number(p.weekday)<0||Number(p.weekday)>6)fail('invalidForm');if(!name||name.length>70||!venue||venue.length>140||!city||!['BG','BS'].includes(p.province))fail('invalidForm');const gid=id(s,'group');s.groups[gid]={id:gid,name,venue,city,province:p.province,ownerId:actorId,adminIds:[],weekday:Number(p.weekday),start:p.start||'20:30',end:p.end||'22:30',priceCents:700,capacity:16,level:'mixed',memberApproval:!!p.memberApproval,bookingApproval:!!p.bookingApproval,description:String(p.description||'').slice(0,1500),history:String(p.history||'').slice(0,1500),demo:true,createdAt:new Date(now).toISOString()};s.memberships[`${gid}:${actorId}`]={groupId:gid,personId:actorId,status:'active',role:'organizer'};record(s,'groupCreated',actorId,{groupId:gid},now);s.lastCreatedGroupId=gid;
 }else if(action==='CREATE_MATCH'||action==='EDIT_MATCH'){
  const old=action==='EDIT_MATCH'?s.matches[p.matchId]:null,g=s.groups[old?.groupId||p.groupId];if(!g)fail('notFound');assertManager(s,actorId,g.id);if(old)assertFuture(old,now);const capacity=Number(p.capacity),priceCents=Math.round(Number(p.price)*100);if(!Number.isInteger(capacity)||capacity<2||capacity>30||!Number.isFinite(priceCents)||priceCents<0||priceCents>100000||!validDateTime(p.date,p.start)||!validDateTime(p.date,p.end)||!String(p.venue||'').trim())fail('invalidForm');let dates=occurrenceDates(p.date,!old&&!!p.weekly,!old&&p.weekly?p.until:p.date,!!p.skipHolidays).filter(d=>!d.skip);if(!dates.length||dates.length>104)fail('invalidDates');if(old&&activeBookings(s,old.id,now).length>capacity)fail('capacityTooSmall');const seriesId=!old&&p.weekly?id(s,'series'):null;
  for(const d of dates){const clock=times(d.date,p.start,p.end);if(Date.parse(clock.startsAt)<=now||Date.parse(clock.endsAt)-Date.parse(clock.startsAt)>24*3600000)fail('futureDate');const mid=old?.id||id(s,'match'),updated={id:mid,groupId:g.id,date:d.date,venue:String(p.venue).trim(),city:g.city,...clock,priceCents,capacity,status:'active',seriesId:old?.seriesId||seriesId,seeded:false};if(old){const slots=slotsFor(updated);if(activeBookings(s,mid,now).some(b=>!slots.includes(b.slot)))fail('occupiedReserve');Object.assign(old,updated);for(const r of values(s.requests))if(r.matchId===mid&&r.status==='pending'&&r.type==='booking')r.expiresAt=new Date(Math.min(Date.parse(r.expiresAt),Date.parse(updated.startsAt))).toISOString();for(const b of activeBookings(s,mid,now))notify(s,b.personId,'matchChanged',{matchId:mid,groupId:g.id},now);}else s.matches[mid]=updated;record(s,old?'matchChanged':'matchCreated',actorId,{groupId:g.id,matchId:mid},now);s.lastCreatedMatchId=mid;}
 }else if(action==='PROFILE'){
  const old=s.profiles[actorId];if(p.name!==undefined){const name=String(p.name).trim();if(!name||name.length>70)fail('invalidForm');old.name=name;}for(const key of ['bio','city'])if(p[key]!==undefined)old[key]=String(p[key]).slice(0,1500);if(p.role!==undefined){if(!ROLES.includes(p.role))fail('invalidForm');old.role=p.role;}if(p.level!==undefined){if(!['beginner','intermediate','advanced'].includes(p.level))fail('invalidForm');old.level=p.level;}for(const key of ['days','strengths'])if(p[key]){if(!Array.isArray(p[key])||p[key].some(v=>key==='days'?!Number.isInteger(v)||v<0||v>6:!['attack','reception','serve','defence','block'].includes(v)))fail('invalidForm');old[key]=[...new Set(p[key])];}if(p.photo!==undefined){if(p.photo&&!/^data:image\/(?:png|jpeg|webp);base64,/.test(p.photo))fail('invalidImage');old.photo=p.photo;}if(p.available!==undefined){const enabled=!old.available&&p.available;old.available=!!p.available;if(enabled){const m=values(s.matches).find(m=>m.status==='active'&&Date.parse(m.startsAt)>now&&availableCount(s,m.id,now)>0);if(m){const inv=id(s,'invite');s.invitations[inv]={id:inv,senderId:s.groups[m.groupId].ownerId,recipientId:actorId,matchId:m.id,status:'pending',createdAt:new Date(now).toISOString()};notify(s,actorId,'invitation',{invitationId:inv,matchId:m.id},now);}}}
 }else if(action==='INVITE'){
  const m=s.matches[p.matchId];assertFuture(m,now);if(!canManage(s,actorId,m.groupId)&&!myBooking(s,actorId,m.id,now))fail('unauthorized');if(!s.profiles[p.personId]||p.personId===actorId||myBooking(s,p.personId,m.id,now)||values(s.invitations).some(i=>i.matchId===m.id&&i.recipientId===p.personId&&i.status==='pending'))fail('duplicateRequest');const inv=id(s,'invite');s.invitations[inv]={id:inv,senderId:actorId,recipientId:p.personId,matchId:m.id,status:'pending',createdAt:new Date(now).toISOString()};notify(s,p.personId,'invitation',{invitationId:inv,matchId:m.id},now);
 }else if(action==='DECIDE_INVITE'){
  const inv=s.invitations[p.id];if(!inv||inv.recipientId!==actorId)fail('unauthorized');if(inv.status!=='pending')fail('alreadyDecided');inv.status=p.accept?'accepted':'rejected';record(s,inv.status,actorId,{matchId:inv.matchId,invitationId:inv.id},now);notify(s,inv.senderId,inv.status,{matchId:inv.matchId},now);
 }else if(action==='RATE'){
  const m=s.matches[p.matchId];if(!m||Date.parse(m.endsAt)>now||!values(s.bookings).some(b=>b.matchId===m.id&&b.personId===actorId&&b.status==='confirmed'))fail('ratingNotAllowed');const key=`${m.id}:${actorId}`;if(s.ratings[key])fail('alreadyRated');const allowed=new Set(['venue',...values(s.bookings).filter(b=>b.matchId===m.id&&b.status==='confirmed'&&b.personId!==actorId).flatMap(b=>['reliability:'+b.personId,'technique:'+b.personId])]);if(Object.keys(p.scores||{}).some(k=>!allowed.has(k)))fail('invalidForm');const scores=Object.fromEntries(Object.entries(p.scores||{}).filter(([,v])=>Number.isInteger(v)&&v>=1&&v<=5));if(!Object.keys(scores).length)fail('invalidForm');s.ratings[key]={matchId:m.id,personId:actorId,scores,createdAt:new Date(now).toISOString()};
 }else if(action==='HOLD_CONFIG'){
  if(!s.authorizedAdmins.includes(actorId))fail('unauthorized');const hours=Number(p.hours);if(!Number.isFinite(hours)||hours<.01||hours>168)fail('invalidForm');s.config.holdHours=hours;
 }else fail('unknownAction');s.revision++;return s;
}
